def choose_move(observation):
    obs = observation or {}
    x = obs.get("self_position", {}).get("x", 0)
    y = obs.get("self_position", {}).get("y", 0)

    best_dx, best_dy = 0, 0

    resources = obs.get("resources", [])
    if resources:
        best_r = None
        best_dist = float("inf")
        for r in resources:
            rx = r.get("x", 0)
            ry = r.get("y", 0)
            d = abs(rx - x) + abs(ry - y)
            if d < best_dist:
                best_dist = d
                best_r = (rx, ry)
        if best_r is not None and best_dist > 0:
            dx = best_r[0] - x
            dy = best_r[1] - y
            return [max(-1, min(1, dx)), max(-1, min(1, dy))]

    obstacles = obs.get("obstacles", [])
    if obstacles:
        # Try to move to a free adjacent cell not in obstacle
        for dx in (-1, 0, 1):
            for dy in (-1, 0, 1):
                if dx == 0 and dy == 0:
                    continue
                nx = x + dx
                ny = y + dy
                blocked = False
                for o in obstacles:
                    ox = o.get("x", 0)
                    oy = o.get("y", 0)
                    if nx == ox and ny == oy:
                        blocked = True
                        break
                if not blocked:
                    return [dx, dy]

    # Fallback: move toward center if grid known and not at center
    w = obs.get("grid_width", 0)
    h = obs.get("grid_height", 0)
    cx = w // 2
    cy = h // 2
    dx = 0
    dy = 0
    if w and h:
        if x < cx:
            dx = 1
        elif x > cx:
            dx = -1
        if y < cy:
            dy = 1
        elif y > cy:
            dy = -1
        if dx != 0 or dy != 0:
            return [dx, dy]

    return [0, 0]
